// =========================================================================
// 🛠️ NORMALIZE VAPI TOOL CALL PAYLOAD
// =========================================================================
const body = $input.first()?.json?.body || {};
const message = body.message || {};
const toolCalls = message.toolCalls || [];

if (!toolCalls.length) {
  return [{
    json: {
      toolName: 'unknown',
      toolCallId: 'unknown',
      args: {},
      rawBody: body
    }
  }];
}

const primaryCall = toolCalls[0];
let parsedArgs = {};
try {
  const rawArgs = primaryCall.function?.arguments;
  parsedArgs = typeof rawArgs === 'string' ? JSON.parse(rawArgs) : (rawArgs || {});
} catch (e) {
  parsedArgs = {};
}

return [{
  json: {
    toolName: primaryCall.function?.name || 'unknown',
    toolCallId: primaryCall.id || 'tool-call-1',
    args: parsedArgs,
    callDetails: message.call || {},
    customer: message.customer || {}
  }
}];

