// =========================================================================
// 🔍 EVALUATE GCAL BOOKING & ASSEMBLE FEEDBACK
// =========================================================================
const gcalRes = $input.first()?.json || {};
const vapiData = $('Normalize Vapi Call').first()?.json || {};
const args = vapiData.args || {};
const toolCallId = vapiData.toolCallId || 'tool-call-1';

const isError = Boolean(gcalRes.error || !gcalRes.id);
let errorMsg = '';
if (gcalRes.error) {
  errorMsg = typeof gcalRes.error === 'object' ? (gcalRes.error.message || JSON.stringify(gcalRes.error)) : String(gcalRes.error);
} else if (!gcalRes.id) {
  errorMsg = 'Calendar event creation did not return an event ID';
}

let responseText = '';
if (!isError) {
  responseText = `Great! I have successfully scheduled your consultation for ${args.customer_name || 'you'} on ${args.start_time}. You will receive confirmation shortly.`;
} else {
  responseText = `I have captured your consultation request for ${args.customer_name || 'you'} on ${args.start_time}. Our calendar sync had a brief delay, so our team will review and confirm with you shortly.`;
}

const alertHtml = `🚨 <b>TAKVİM ENTEGRASYON UYARISI</b>\n━━━━━━━━━━━━━━━━━━━━━\n⚠️ <b>Durum:</b> Randevu Google Takvim'e yazılamadı!\n👤 <b>Müşteri:</b> ${args.customer_name || 'Bilinmiyor'} (<code>${args.customer_phone || vapiData.customer?.number || 'Belirtilmedi'}</code>)\n📅 <b>İstenen Randevu:</b> ${args.start_time || 'Belirtilmedi'}\n📝 <b>Konu:</b> ${args.summary || 'Consultation'}\n❌ <b>Hata:</b> <code>${errorMsg}</code>\n\n👉 <i>Lütfen takvimi manuel kontrol edin veya n8n kimlik doğrulamasını (Google Calendar account) yenileyin.</i>`;

return [{
  json: {
    isError,
    errorMsg,
    responseText,
    alertHtml,
    toolCallId,
    chatId: '1519369571'
  }
}];

