// =========================================================================
// ✍️ EXTRACT CALL METRICS & PREPARE AI ANALYSIS PROMPT
// =========================================================================
const body = $input.first()?.json?.body || {};
const message = body.message || {};

// Only process full end-of-call report (ignore status-update / ping events)
const msgType = message.type || body.type || '';
if (msgType && msgType !== 'end-of-call-report') {
  return [];
}

const transcript = message.transcript || body.transcript || 'No transcript provided.';
const durationSeconds = message.durationSeconds || body.durationSeconds || 0;
const recordingUrl = message.recordingUrl || message.stereoRecordingUrl || body.recordingUrl || '';
const customerNumber = message.customer?.number || message.call?.customer?.number || 'Web/Direct Caller';

const prompt = `You are an executive operational analyst. Analyze the following telephone call transcript between a Voice AI Assistant (Alex) and an inbound caller.

TRANSCRIPT:
"""
${transcript}
"""

CALL METADATA:
- Duration: ${durationSeconds} seconds
- Caller Phone: ${customerNumber}

OUTPUT SCHEMA (Return clean JSON only):
{
  "caller_name": "Full name or 'Not Provided'",
  "caller_phone": "${customerNumber}",
  "call_duration_seconds": ${durationSeconds},
  "call_sentiment": "Positive" | "Neutral" | "Frustrated",
  "lead_tier": "🔥 HOT LEAD" | "⚡ WARM LEAD" | "❄️ COLD LEAD",
  "appointment_booked": true | false,
  "appointment_details": "Date & Time string, or 'None'",
  "summary_bullet_points": ["Key point 1", "Key point 2"],
  "action_items": ["Concrete follow-up action 1"],
  "escalation_flag": true | false
}`;

return [{
  json: {
    transcript: transcript,
    durationSeconds: durationSeconds,
    recordingUrl: recordingUrl,
    customerNumber: customerNumber,
    aiPrompt: prompt
  }
}];

// =========================================================================
// 📊 PARSE STRUCTURED ANALYSIS & ASSEMBLE TELEGRAM REPORT
// =========================================================================
const res = $input.first().json;
const prepData = $('Extract Call & Prepare Prompt').first().json;

let analysis = {};
try {
  let raw = res.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
  raw = raw.replace(/```json/g, '').replace(/```/g, '').trim();
  analysis = JSON.parse(raw);
} catch (e) {
  analysis = {
    caller_name: 'Caller',
    caller_phone: prepData.customerNumber,
    call_duration_seconds: prepData.durationSeconds,
    call_sentiment: 'Neutral',
    lead_tier: '⚡ WARM LEAD',
    appointment_booked: false,
    appointment_details: 'None',
    summary_bullet_points: ['Call completed without full AI parsing.'],
    action_items: ['Review raw call transcript.']
  };
}

const duration = analysis.call_duration_seconds || prepData.durationSeconds || 0;
const mins = Math.floor(duration / 60);
const secs = duration % 60;

const bullets = (analysis.summary_bullet_points || []).map(p => `• ${p}`).join('\n') || '• No summary available';
const actions = (analysis.action_items || []).map(a => `👉 ${a}`).join('\n') || '👉 Follow up with caller';
const apptBadge = analysis.appointment_booked ? `✅ ${analysis.appointment_details || 'Randevu Alındı'}` : '❌ Alınmadı';

const reportHtml = `📞 <b>YENİ SESLİ GÖRÜŞME RAPORU</b>
━━━━━━━━━━━━━━━━━━━━━
👤 <b>Arayan:</b> ${analysis.caller_name || 'Bilinmiyor'} (<code>${analysis.caller_phone || prepData.customerNumber}</code>)
⏱ <b>Süre:</b> ${mins} dk ${secs} sn
🎯 <b>Lead Durumu:</b> ${analysis.lead_tier || '⚡ WARM LEAD'}
🧠 <b>Duygu:</b> ${analysis.call_sentiment || 'Neutral'}
📅 <b>Randevu:</b> ${apptBadge}

📝 <b>Görüşme Özeti:</b>
${bullets}

📌 <b>Aksiyon Maddeleri:</b>
${actions}`;

return [{
  json: {
    ...analysis,
    reportHtml: reportHtml,
    recordingUrl: prepData.recordingUrl,
    chatId: '1519369571'
  }
}];
